import csv
tid='af4b8334-3dca-548d-b215-2cb64a0aa2c0'
vals={}
with open(VALUES_CSV) as f:
    rd=csv.DictReader(f)
    for row in rd:
        if row['timeseries_id']==tid:
            vals[row['timestamp']]=float(row['value'])
ks=[k for k in vals if k.startswith('2018-07-19')]
print(ks)
mx=max(vals.values())
for k in ks:
    print(k, vals[k], vals[k]/mx)
